import{_ as s,o as t,c as n,ah as r}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Parents","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/secretariat/parents.md","filePath":"src/guide/secretariat/parents.md"}'),a={name:"guide/secretariat/parents.md"};function i(o,e,l,p,u,c){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="parents" tabindex="-1">Parents <a class="header-anchor" href="#parents" aria-label="Permalink to &quot;Parents&quot;">​</a></h1><p>La page <strong>Parents</strong>, dans l&#39;espace <strong>Élèves et admissions</strong>, rassemble les parents des élèves : leurs coordonnées, leurs enfants et l&#39;état de leur compte. Elle sert surtout à compléter les adresses e-mail et les numéros de téléphone qui manquent, puis à inviter les parents dans l&#39;application.</p><p>Elle est ouverte à l&#39;administration et au secrétariat. L&#39;administration voit tous les parents. Le secrétariat voit les parents des élèves inscrits sur <strong>son site</strong>, celui de sa fiche employé. Une personne du secrétariat sans site sur sa fiche voit tous les parents.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>On ne rattache pas un enfant à un parent depuis cette page : cela se fait toujours depuis la fiche de l&#39;élève, page <strong>Tuteurs</strong>, par l&#39;administration.</p></div><h2 id="la-liste" tabindex="-1">La liste <a class="header-anchor" href="#la-liste" aria-label="Permalink to &quot;La liste&quot;">​</a></h2><p>Chaque ligne montre le parent, son adresse e-mail, ses enfants avec leur classe de l&#39;année (série et site compris), son téléphone et l&#39;état de son compte :</p><ul><li><strong>Sans e-mail</strong> : le parent n&#39;a pas encore d&#39;adresse e-mail. C&#39;est le cas des parents repris de l&#39;ancienne plateforme sans adresse. On ne peut pas l&#39;inviter tant qu&#39;elle n&#39;est pas saisie.</li><li><strong>Non invité</strong> : l&#39;adresse est connue, aucune invitation n&#39;est partie.</li><li><strong>Invité</strong> : une invitation a été envoyée et son lien est encore valable.</li><li><strong>Invitation expirée</strong> : le lien a expiré sans que le parent ne l&#39;utilise.</li><li><strong>Activé</strong> : le parent a choisi son mot de passe.</li></ul><p>Pour retrouver un parent, tapez son nom, son adresse, son téléphone ou le nom d&#39;un de ses enfants, puis cliquez sur <strong>Rechercher</strong>. Les listes <strong>Tous les états</strong> et <strong>Tous les sites</strong> (quand vous voyez plusieurs sites) filtrent la liste.</p><p><strong>Exporter en CSV</strong> télécharge la liste telle qu&#39;elle est filtrée. Avec le filtre <strong>Sans e-mail</strong>, c&#39;est la liste des familles à appeler pour obtenir leur adresse.</p><h2 id="corriger-les-coordonnees" tabindex="-1">Corriger les coordonnées <a class="header-anchor" href="#corriger-les-coordonnees" aria-label="Permalink to &quot;Corriger les coordonnées&quot;">​</a></h2><p>Cliquez sur <strong>Modifier</strong> au bout de la ligne.</p><ol><li>Corrigez le <strong>Nom</strong>, l&#39;<strong>Adresse e-mail</strong> ou le <strong>Téléphone</strong>. Le téléphone s&#39;écrit avec l&#39;indicatif du pays, par exemple +228 90 11 22 33.</li><li>Pour un parent sans e-mail, laissez le champ vide tant que vous n&#39;avez pas son adresse : il garde son état <strong>Sans e-mail</strong>.</li><li>Renseignez, si vous les connaissez, la <strong>Civilité</strong> (M., Mme, Mlle), la <strong>Profession</strong>, la <strong>Nationalité</strong> et la <strong>Boîte postale</strong>. La civilité précède le nom du parent sur le bulletin au modèle Traditionnel ; ces quatre champs figurent aussi dans l&#39;export CSV.</li><li>Cliquez sur <strong>Enregistrer les modifications</strong>.</li></ol><p>Dès qu&#39;une vraie adresse est enregistrée, le parent passe à <strong>Non invité</strong> et peut être invité. Changer l&#39;adresse d&#39;un compte pas encore activé annule l&#39;invitation déjà envoyée, puisqu&#39;elle était partie à l&#39;ancienne adresse.</p><p>La rubrique <strong>Enfants</strong> rappelle ses enfants et leur classe. L&#39;administration y trouve un lien vers les <strong>Tuteurs de l&#39;élève</strong>.</p><h2 id="inviter-le-parent" tabindex="-1">Inviter le parent <a class="header-anchor" href="#inviter-le-parent" aria-label="Permalink to &quot;Inviter le parent&quot;">​</a></h2><p>Dans la rubrique <strong>Accès à l&#39;application</strong> :</p><ul><li><strong>Envoyer l&#39;invitation</strong> envoie au parent un e-mail avec un lien pour choisir son mot de passe. Le lien reste valable 7 jours. Pour un parent déjà invité, le bouton devient <strong>Renvoyer l&#39;invitation</strong>, et le nouveau lien remplace l&#39;ancien.</li><li><strong>Copier un lien d&#39;invitation</strong>, si l&#39;e-mail n&#39;arrive pas : le lien s&#39;affiche et se copie, pour le remettre au parent par un autre moyen. Ce lien remplace celui envoyé par e-mail.</li></ul><p>Un parent qui a activé son compte n&#39;a plus besoin d&#39;invitation : s&#39;il a oublié son mot de passe, il utilise <strong>Mot de passe oublié</strong> sur la page de connexion.</p>',18)])])}const v=s(a,[["render",i]]);export{g as __pageData,v as default};
